INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130011, "2024/10/31 12:00:00", 100, 3001100, "2030/01/01 14:59:59", 2, -416.5, 3001, 0.0, "ヤマト", 2.1, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130011, "2024/10/31 12:00:00", 101, 3001101, "2030/01/01 14:59:59", 2, -416.5, 3001, 0.0, "ヤマト", 5.68, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 4);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130011, "2024/10/31 12:00:00", 102, 3001102, "2030/01/01 14:59:59", 1, -416.5, 3001, 0.0, "ヤマト", 0.0, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 100, 3002100, "2030/01/01 14:59:59", 1, -416.5, 3002, 0.0, "フブキ", 0.0, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 101, 3002101, "2030/01/01 14:59:59", 1, -416.5, 3002, 0.0, "フブキ", 0.0, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 102, 3002102, "2030/01/01 14:59:59", 2, -416.5, 3002, 0.0, "フブキ", 8.53, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 5);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 103, 3002103, "2030/01/01 14:59:59", 1, -416.5, 3002, 0.0, "フブキ", 5.67, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 104, 3002104, "2030/01/01 14:59:59", 1, -416.5, 3002, 0.0, "フブキ", 0.0, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 300, 3002300, "2030/01/01 14:59:59", 3, -416.5, 3004, 0.0, "フブキ", 0.0, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 301, 3002400, "2030/01/01 14:59:59", 7, -416.5, 3005, 0.0, "フブキ", 0.0, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 200, 3003200, "2030/01/01 14:59:59", 1, -416.5, 3003, 0.0, "フブキ", 4.4, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 201, 3003201, "2030/01/01 14:59:59", 7, -416.5, 3003, 0.0, "フブキ", 0.0, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (130211, "2024/10/31 12:00:00", 202, 3003202, "2030/01/01 14:59:59", 2, -416.5, 3003, 0.0, "フブキ", 5.6, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 1);
